def count_errors(codes):
    counts = {}
    for code in codes:
        counts[code] = counts.get(code, 0) + 1
    return counts

from collections import Counter

def count_errors_alternative(codes):
    return dict(Counter(codes))

def group_rows(rows):
    groups = {}
    for row in rows:
        key = row["customer_id"]
        groups.setdefault(key, []).append(row)
    return groups

from collections import defaultdict

def group_rows_alternative(rows):
    groups = defaultdict(list)
    for row in rows:
        groups[row["customer_id"]].append(row)
    return dict(groups)

def latest_records(rows):
    latest = {}
    for row in rows:
        key = row["entity_id"]
        previous = latest.get(key)
        if previous is None or row["updated_at"] >= previous["updated_at"]:
            latest[key] = row
    return latest

def latest_records_alternative(rows):
    ordered = sorted(rows, key=lambda row: row["updated_at"])
    return {row["entity_id"]: row for row in ordered}

